Fixpoint memcmp_model (xs ys : list Z) : Z :=
  match xs, ys with
  | x :: xs', y :: ys' => if x =? y then memcmp_model xs' ys' else x - y
  | _, _ => 0
  end.

Lemma memcmp_model_zero : forall xs ys, length xs = length ys ->
  (memcmp_model xs ys = 0 <-> xs = ys).
Proof.
  induction xs as [|x xs IH]; intros [|y ys] L; cbn in *; try (split; [intros; reflexivity | intros; reflexivity]); try lia.
  destruct (Z.eqb_spec x y) as [<-|NE].
  - rewrite IH by lia. split; [intros ->; reflexivity | intros H; injection H; auto].
  - split; [intros; lia | intros H; injection H; intros; lia].
Qed.

Lemma memcmp_model_range : forall (ls rs : list byte),
  -255 <= memcmp_model (zbytes ls) (zbytes rs) <= 255.
Proof.
  induction ls as [|a ls IH]; intros [|b rs]; cbn; try lia.
  pose proof (zb_range a). pose proof (zb_range b).
  destruct (Z.eqb_spec (zb a) (zb b)); [apply IH | lia].
Qed.

Lemma memcmp_model_zbytes_zero : forall (ls rs : list byte), length ls = length rs ->
  (memcmp_model (zbytes ls) (zbytes rs) = 0 <-> ls = rs).
Proof.
  intros ls rs L. rewrite memcmp_model_zero by (unfold zbytes; rewrite !length_map; exact L).
  split; [| intros ->; reflexivity].
  revert rs L. induction ls as [|a ls IH]; intros [|b rs] L E; cbn in *; try reflexivity; try discriminate.
  injection E as E1 E2. f_equal; [apply bv_eq; exact E1 | apply IH; [lia | exact E2]].
Qed.

(* [comment removed for export] *)
Lemma memcmp_word_zero : forall (ls rs : list byte), length ls = length rs ->
  (bv_unsigned (wz (memcmp_model (zbytes ls) (zbytes rs))) = 0 <-> ls = rs).
Proof.
  intros ls rs L. rewrite <- memcmp_model_zbytes_zero by exact L.
  pose proof (memcmp_model_range ls rs) as R. set (v := memcmp_model _ _) in *.
  unfold wz. rewrite Z_to_bv_unsigned. unfold bv_wrap, bv_modulus. change (2 ^ Z.of_N 64) with (2^64).
  split; intros H; [| rewrite H; reflexivity].
  destruct (Z.eq_dec v 0) as [E|NE]; [exact E|]. exfalso.
  destruct (Z.lt_ge_cases v 0).
  - rewrite <- (Z.mod_add v 1 (2^64)) in H by lia. rewrite Z.mod_small in H; lia.
  - rewrite Z.mod_small in H; lia.
Qed.

