Definition memcmp_post_v (v : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (L R : Z) (ls rs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz v) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [] m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ bytes_at usegs m' L ls /\ bytes_at usegs m' R rs.

Definition memcmp_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (L R : Z) (ls rs : list byte) (m : mem) : machine_state -> Prop :=
  memcmp_post_v (memcmp_model (zbytes ls) (zbytes rs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc L R ls rs m.

Definition memcmp_stmt_at (entry : Z) : Prop :=
  forall (L R : Z) (ls rs : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  bytes_at usegs m L ls -> bytes_at usegs m R rs -> length rs = length ls -> Z.of_nat (length ls) < 2^64 ->
  mem_inv usegs m ->
  evt usegs (memcmp_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc L R ls rs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz L) (wz R) (wz (Z.of_nat (length ls))) a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 entry) fc None m (seg_rom usegs)).

Definition memcmp_stmt : Prop := memcmp_stmt_at P_MEMCMP.
Definition bcmp_stmt : Prop := memcmp_stmt_at P_BCMP.

